 private void ResetFoxEstimate(){foxEstimateGeneration++;foxEstimateCancel?.Cancel();foxEstimateCancel?.Dispose();foxEstimateCancel=null;foxEstimateSnapshot=null;foxMap.SetEstimate(null);foxEstimateStatus.Text="Rough source area: not calculated";}
 private async Task CalculateFoxEstimate()
 {
