  try{var result=await Task.Run(()=>FoxLocator.Estimate(snapshot,token),token);if(generation!=foxEstimateGeneration||closing)return;foxEstimateSnapshot=new(result,DateTimeOffset.UtcNow,snapshot.LastOrDefault()?.Utc,snapshot.Length);PresentFoxEstimate(DateTimeOffset.UtcNow);}
  catch(OperationCanceledException){}catch(Exception ex){if(generation==foxEstimateGeneration)foxEstimateStatus.Text="Estimate unavailable: "+ex.Message;}
 }
 private void PresentFoxEstimate(DateTimeOffset now){if(foxEstimateSnapshot is not {} snapshot)return;foxEstimateStatus.Text=snapshot.Describe(foxSession.Running,now);foxMap.SetEstimate(snapshot.Overlay(foxSession.Running,now));}
